/**
 * Create a new plandetail with proper date and relation handling
 */
export async function createPlanDetail(data: CreatePlanDetailInput): Promise<PlanDetailDb> {
  // Validate foreign keys exist

  if (data.planId) {
    const planExists = await db
      .select({ id: planSchema.id })
      .from(planSchema)
      .where(eq(planSchema.id, data.planId))
      .limit(1);

    if (!planExists.length) {
      throw new Error('Plan not found');
    }
  }

  const [plandetail] = await db
    .insert(planDetailSchema)
    .values({
      locationCode: data.locationCode,
      locationType: data.locationType,
      productCode: data.productCode,
      productSubCode: data.productSubCode,
      plannedQuantity: data.plannedQuantity,
      actualQuantity: data.actualQuantity,
      plannedStartDate: data.plannedStartDate ? new Date(data.plannedStartDate) : null,
      plannedEndDate: data.plannedEndDate ? new Date(data.plannedEndDate) : null,
      actualStartDate: data.actualStartDate ? new Date(data.actualStartDate) : null,
      actualEndDate: data.actualEndDate ? new Date(data.actualEndDate) : null,
      status: data.status,
      priority: data.priority,
      note: data.note,
      ownerId: data.ownerId,
      planId: data.planId,
    } as any)
    .returning();

  if (!plandetail) {
    throw new Error('Failed to create plandetail');
  }

  return plandetail;
}

/**
 * Get plandetails by organization through plan relationship
 * Shows plandetails that belong to plans accessible by the organization
 */
export async function getPlanDetailsByOwner(
  params: PlanDetailListParamsWithOwner,
): Promise<PlanDetailDb[] | PlanDetailWithRelations[]> {
  const {
    ownerId: orgId, // ownerId is now actually orgId from the route
    page = 1,
    limit = 10,
    search,
    planCode,
    productCode,
    productName,
    sortBy = 'createdAt',
    sortOrder = 'desc',
    includeRelations = false,
  } = params;

  const offset = (page - 1) * limit;

  let baseQuery;
  if (includeRelations) {
    baseQuery = db.select({
      id: planDetailSchema.id,
      ownerId: planDetailSchema.ownerId,
      planId: planDetailSchema.planId,
      locationCode: planDetailSchema.locationCode,
      locationType: planDetailSchema.locationType,
      productCode: planDetailSchema.productCode,
      productSubCode: planDetailSchema.productSubCode,
      plannedQuantity: planDetailSchema.plannedQuantity,
      actualQuantity: planDetailSchema.actualQuantity,
      plannedStartDate: planDetailSchema.plannedStartDate,
      plannedEndDate: planDetailSchema.plannedEndDate,
      actualStartDate: planDetailSchema.actualStartDate,
      actualEndDate: planDetailSchema.actualEndDate,
      status: planDetailSchema.status,
      priority: planDetailSchema.priority,
      note: planDetailSchema.note,
      updatedAt: planDetailSchema.updatedAt,
      createdAt: planDetailSchema.createdAt,
      plan: {
        id: planSchema.id,
        planCode: planSchema.planCode,
      },
    }).from(planDetailSchema)
      .leftJoin(planSchema, eq(planDetailSchema.planId, planSchema.id))
      .leftJoin(productSchema, eq(planDetailSchema.productCode, productSchema.productCode));
  } else {
    baseQuery = db.select().from(planDetailSchema)
      .innerJoin(planSchema, eq(planDetailSchema.planId, planSchema.id))
      .leftJoin(productSchema, eq(planDetailSchema.productCode, productSchema.productCode));
  }

  // Build where conditions safely
  // Filter by plan's ownerId instead of plandetail's ownerId to get org-wide access
  const whereConditions: (SQL | undefined)[] = [eq(planSchema.ownerId, orgId)];

  if (search) {
    const searchTerm = `%${search}%`;
    const searchConditions: (SQL | undefined)[] = [
      ilike(planDetailSchema.locationCode, searchTerm),
      ilike(planDetailSchema.productSubCode, searchTerm),
    ];

    // Always include plan search since we now always JOIN with plan
    searchConditions.push(ilike(planSchema.planCode, searchTerm));
    searchConditions.push(ilike(planSchema.planName, searchTerm));

    const validSearchConditions = searchConditions.filter((c): c is SQL => !!c);
    if (validSearchConditions.length > 0) {
      whereConditions.push(or(...validSearchConditions));
    }
  }

  // Individual filter conditions
  if (planCode) {
    whereConditions.push(ilike(planSchema.planCode, `%${planCode}%`));
  }

  if (productCode) {
    whereConditions.push(ilike(planDetailSchema.productCode, `%${productCode}%`));
  }

  if (productName) {
    whereConditions.push(ilike(productSchema.productName, `%${productName}%`));
  }

  // Safe sorting with switch statement
  let orderBy;
  switch (sortBy) {
    case 'createdAt':
      orderBy = sortOrder === 'asc' ? asc(planDetailSchema.createdAt) : desc(planDetailSchema.createdAt);
      break;
    case 'updatedAt':
      orderBy = sortOrder === 'asc' ? asc(planDetailSchema.updatedAt) : desc(planDetailSchema.updatedAt);
      break;
    case 'productSubCode':
      orderBy = sortOrder === 'asc' ? asc(planDetailSchema.productSubCode) : desc(planDetailSchema.productSubCode);
      break;
    case 'locationCode':
      orderBy = sortOrder === 'asc' ? asc(planDetailSchema.locationCode) : desc(planDetailSchema.locationCode);
      break;
    default:
      orderBy = desc(planDetailSchema.createdAt);
  }

  const results = await baseQuery
    .where(and(...whereConditions.filter((c): c is SQL => !!c)))
    .orderBy(orderBy)
    .limit(limit)
    .offset(offset);

  if (includeRelations) {
    return results.map((result: any) => {
      const { plan, ...rest } = result as any;
      return { ...rest, plan: plan ?? undefined };
    });
  }

  return results;
}

/**
 * Get plandetail by ID with ownership check and relations
 */
export async function getPlanDetailById(
  id: number,
  orgId: string,
  includeRelations = false,
): Promise<PlanDetailDb | PlanDetailWithRelations | undefined> {
  let baseQuery;
  if (includeRelations) {
    baseQuery = db.select({
      id: planDetailSchema.id,
      ownerId: planDetailSchema.ownerId,
      planId: planDetailSchema.planId,
      locationCode: planDetailSchema.locationCode,
      locationType: planDetailSchema.locationType,
      productCode: planDetailSchema.productCode,
      productSubCode: planDetailSchema.productSubCode,
      plannedQuantity: planDetailSchema.plannedQuantity,
      actualQuantity: planDetailSchema.actualQuantity,
      plannedStartDate: planDetailSchema.plannedStartDate,
      plannedEndDate: planDetailSchema.plannedEndDate,
      actualStartDate: planDetailSchema.actualStartDate,
      actualEndDate: planDetailSchema.actualEndDate,
      status: planDetailSchema.status,
      priority: planDetailSchema.priority,
      note: planDetailSchema.note,
      updatedAt: planDetailSchema.updatedAt,
      createdAt: planDetailSchema.createdAt,
      plan: {
        id: planSchema.id,
        planCode: planSchema.planCode,
      },
    }).from(planDetailSchema)
      .leftJoin(planSchema, eq(planDetailSchema.planId, planSchema.id))
      .leftJoin(productSchema, eq(planDetailSchema.productCode, productSchema.productCode));
  } else {
    baseQuery = db.select().from(planDetailSchema)
      .innerJoin(planSchema, eq(planDetailSchema.planId, planSchema.id))
      .leftJoin(productSchema, eq(planDetailSchema.productCode, productSchema.productCode));
  }

  const [result] = await baseQuery
    .where(and(
      eq(planDetailSchema.id, id),
      eq(planSchema.ownerId, orgId),
    ))
    .limit(1);

  if (!result) {
    return undefined;
  }

  if (includeRelations) {
    const { plan, ...rest } = result as any;
    return { ...rest, plan: plan ?? undefined };
  }

  return result;
}

