/**
 * Delete plandetail with ownership check and cascade handling
 */
export async function deletePlanDetail(id: number, orgId: string): Promise<void> {
  // First check if plandetail exists and user has access through plan ownership
  const existingPlanDetail = await getPlanDetailById(id, orgId);
  if (!existingPlanDetail) {
    throw new Error('PlanDetail not found or access denied');
  }

  const result = await db
    .delete(planDetailSchema)
    .where(eq(planDetailSchema.id, id));

  if (!result) {
    throw new Error('Failed to delete PlanDetail');
  }
}

/**
 * Get relation options for dropdowns
 */
export async function getPlanDetailRelationOptions(): Promise<{
  plans: Array<{ id: number; planCode: string }>;
  products: Array<{ id: number; productCode: string; productName: string }>;
  locationCodes: Array<{ locationCode: string; tableName?: string }>;
  productSubCodes: Array<{ productSubCode: string; productSubDetail: string; productCode: string }>;
}> {
  try {
    // Get plans
    const planOptions = await db.select({
      id: planSchema.id,
      planCode: planSchema.planCode,
    }).from(planSchema).orderBy(asc(planSchema.planCode));

    // Get products
    const productOptions = await db.select({
      id: productSchema.id,
      productCode: productSchema.productCode,
      productName: productSchema.productName,
    }).from(productSchema).orderBy(asc(productSchema.productCode));

    // Get location codes from work tables
    const locationOptions = await db.select({
      locationCode: workTableSchema.locationCode,
      tableName: workTableSchema.tableName,
    }).from(workTableSchema)
      .orderBy(asc(workTableSchema.locationCode));

    // Get product sub codes
    const productSubOptions = await db.select({
      productSubCode: productSubSchema.productSubCode,
      productSubDetail: productSubSchema.productSubDetail,
      productCode: productSubSchema.productCode,
    }).from(productSubSchema).orderBy(asc(productSubSchema.productSubCode));

    return {
      plans: planOptions,
      products: productOptions,
      locationCodes: locationOptions.filter((item: any) => item.locationCode != null) as Array<{ locationCode: string; tableName?: string }>,
      productSubCodes: productSubOptions,
    };
  } catch (error) {
    console.error('Error fetching relation options:', error);
    return {
      plans: [],
      products: [],
      locationCodes: [],
      productSubCodes: [],
    };
  }
}

/**
 * Get plandetail statistics
 */
export async function getPlanDetailStats(orgId: string): Promise<PlanDetailStats> {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const thisWeekStart = new Date(today);
  thisWeekStart.setDate(today.getDate() - today.getDay());
  const thisMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);

  const [totalResult, todayResult, thisWeekResult, thisMonthResult] = await Promise.all([
    db.select({ count: count() })
      .from(planDetailSchema)
      .innerJoin(planSchema, eq(planDetailSchema.planId, planSchema.id))
      .where(eq(planSchema.ownerId, orgId)),
    db.select({ count: count() })
      .from(planDetailSchema)
      .innerJoin(planSchema, eq(planDetailSchema.planId, planSchema.id))
      .where(and(eq(planSchema.ownerId, orgId), gte(planDetailSchema.createdAt, today))),
    db.select({ count: count() })
      .from(planDetailSchema)
      .innerJoin(planSchema, eq(planDetailSchema.planId, planSchema.id))
      .where(and(eq(planSchema.ownerId, orgId), gte(planDetailSchema.createdAt, thisWeekStart))),
    db.select({ count: count() })
      .from(planDetailSchema)
      .innerJoin(planSchema, eq(planDetailSchema.planId, planSchema.id))
      .where(and(eq(planSchema.ownerId, orgId), gte(planDetailSchema.createdAt, thisMonthStart))),
  ]);

  return {
    total: totalResult[0]?.count ?? 0,
    today: todayResult[0]?.count ?? 0,
    thisWeek: thisWeekResult[0]?.count ?? 0,
    thisMonth: thisMonthResult[0]?.count ?? 0,
  };
}
